export const BODY: string = "\n<p>الفافيكون هو تلك الأيقونة الصغيرة التي تظهر في تبويب المتصفح بجانب عنوان الصفحة. غالبًا ما تكون أول تفصيل بصري يلاحظه الزائر، وترافق موقعك في الإشارات المرجعية والسجل والشاشة الرئيسية.</p>\n<p>لا يفكر أحد تقريبًا في الفافيكون بوعي، لكن عندما يكون مفقودًا أو ضبابيًا، يبدو الموقع غير مكتمل. أيقونة حادة تنقل العناية والاحترافية قبل أن يقرأ أحد كلمة واحدة من موقعك.</p>\n<p>في هذا الدليل نشرح ما يفعله مولد الفافيكون وما هي الملفات التي تحملها حزمة أيقونات كاملة وكيف تحوّل شعارك إلى حزمة مكتملة باستخدام <a href=\"/ar/munshi-favicon/\">مولد الفافيكون</a> المجاني في CompressMyPic. كل شيء يحدث في متصفحك.</p>\n<h2 id=\"what-is-a-favicon\">ما هو الفافيكون؟</h2>\n<p>الفافيكون ملف صورة صغير يمثل موقع ويب داخل المتصفح. يظهر في شريط التبويبات وقائمة الإشارات وصفحة السجل، وفي بعض الأجهزة كأيقونة شاشة رئيسية.</p>\n<p>الاسم يأتي من الإنجليزية favorite icon أي الأيقونة المفضلة، لأن المتصفحات الأولى عرضته بجانب الصفحات المحفوظة. والملف الكلاسيكي هو favicon.ico، صيغة حاوية خاصة تستطيع حفظ أحجام أيقونات عدة في ملف واحد. والمتصفحات الحديثة تقبل أيضًا أيقونات PNG.</p>\n<h2 id=\"why-every-website-needs-a-favicon\">لماذا يحتاج كل موقع إلى فافيكون</h2>\n<p>الموقع دون فافيكون يعرض في التبويب أيقونة عامة لكرة أرضية أو مستند فارغ. من يبقي تبويبات كثيرة مفتوحة يتنقل بالأيقونات، والتبويب الفارغ يصعب إيجاده.</p>\n<p>الفافيكون يظهر أيضًا في الإشارات المرجعية وسجل المتصفح. وعندما يحفظ شخص صفحتك ويعود بعد أيام، تكون الأيقونة هي الدليل البصري الذي يحدد موقعك بين عشرات المحفوظات. وفي الجوال، يغذي الفافيكون الأيقونة المستخدمة عندما يضيف شخص موقعك إلى الشاشة الرئيسية.</p>\n<h2 id=\"what-the-favicon-generator-creates\">ما الذي ينشئه مولد الفافيكون</h2>\n<p>مولد الفافيكون يحوّل شعارًا أو رسمًا ترفعه إلى حزمة أيقونات كاملة. ينشئ ملف favicon.ico متعدد الأحجام وأيقونات Apple Touch وأيقونات أندرويد كروم 192 في 192 و512 في 512، إضافة إلى ملف site.webmanifest.</p>\n<p>كل شيء يأتي معبأ في تنزيل ZIP واحد، فتستلم كل الملفات دفعة واحدة. ويمكنك أيضًا تنزيل ملفات منفردة مثل favicon.ico أو apple-touch-icon.png إذا احتجت واحدًا فقط. وملف favicon.ico الناتج ثنائي ICO حقيقي متعدد الإطارات لا PNG معاد تسميته.</p>\n<h2 id=\"choosing-a-source-image\">كيف تختار الصورة المصدر</h2>\n<p>شعار مربع بصيغة PNG أو SVG يعطي أنقى النتائج. SVG مثالي لأنه يتحجّم دون فقدان الحواف إلى أي حجم، بينما PNG عالي الدقة يعمل جيدًا بشرط أن تبدأ كبيرًا.</p>\n<p>ابدأ بأكبر نسخة من شعارك تستطيع إيجادها. صورة 1024 في 1024 بكسل تتصغر دون مشاكل إلى 16 بكسل، بينما صورة 64 بكسل ممددة إلى الأعلى تبدو ناعمة. والشعارات ذات الخلفية الشفافة تبدو أفضل غالبًا في التبويبات، لأن لون التبويب يظهر حول العلامة.</p>\n<h2 id=\"padding-corner-radius-and-background-fill\">الحشو ونصف قطر الزاوية ولون الخلفية</h2>\n<p>الحشو يتحكم في الهواء بين شعارك وحافة لوحة الأيقونة. شعار يلامس الحواف يبدو ضيقًا عند 16 بكسل، فقليل من الحشو يبقي العلامة مقروءة. والحشو الزائد يصغّر العلامة كثيرًا.</p>\n<p>نصف قطر الزاوية يدوّر زوايا خلفية الأيقونة. نصف قطر صغير ينعّم الشكل، بينما كبير يحوّل الأيقونة إلى دائرة. ولون الخلفية يحدد ما يوجد خلف شعار شفاف. ملء صلب يجعل الأيقونة تبرز في أي لون تبويب، وهذا مفيد عندما يكون الشعار رفيعًا أو شاحبًا.</p>\n<h2 id=\"light-and-dark-tab-previews\">معاينات التبويبات الفاتحة والداكنة</h2>\n<p>يعرض المولد أيقونتك فوق خلفيات تبويب فاتحة وداكنة. هذه المعاينة مهمة لأن شعارًا داكنًا يختفي في تبويب داكن وشعارًا فاتحًا يضيع في تبويب فاتح. وكثير من المواقع تكتشف المشكلة بعد النشر فقط.</p>\n<p>راجع المعاينتين قبل التنزيل. إذا كان شعارك داكنًا، أضف ملء خلفية فاتحًا أو حدًا شاحبًا لينجو في الوضع الداكن. وإذا كان فاتحًا، فملء داكن أو حد داكن يحافظ عليه ظاهرًا. وبعض المصممين يضيفون شكل خلفية خفيفًا خلف العلامة لحل هذه المشكلة بالضبط.</p>\n<h2 id=\"the-html-snippet-and-file-placement\">مقتطف HTML وأين تذهب الملفات</h2>\n<p>بعد توليد الحزمة، ترفع الملفات إلى موقعك وتضيف مقتطف HTML قصيرًا في قسم head في صفحاتك. المقتطف يخبر المتصفح أين يعيش كل أيقونة، بما فيها favicon.ico وأيقونة Apple وملف البيان.</p>\n<p>المكان المعتاد للملفات هو مجلد جذر موقعك، نفس المجلد الذي توجد فيه صفحتك الرئيسية. المتصفحات تبحث عن favicon.ico في الجذر افتراضيًا، فوجوده هناك يزيل الحاجة إلى مقتطف في كثير من الحالات. والمقتطف يعمل مع مواقع HTML البسيطة ومع أطر مثل React وNext.js.</p>\n<h2 id=\"apple-touch-icons-and-android-icons\">أيقونات Apple Touch وأيقونات أندرويد</h2>\n<p>أجهزة Apple تستخدم أيقونة Apple Touch 180 في 180 بكسل عندما يضيف زائر موقعك إلى الشاشة الرئيسية. وتتجاهل Apple الشفافية في هذه الأيقونة وتملأ المناطق الشفافة بالأسود.</p>\n<p>شعار فوق مربع بلون علامتك هو الخيار الآمن. أما أجهزة أندرويد فتقرأ أيقونات بيان الويب: 192 في 192 للشاشة الرئيسية و512 في 512 لشاشة الترحيب ورسالة التثبيت. وكلا الحجمين يأتيان في الحزمة، وهذه الأيقونات الأكبر مهمة لأنها تُعرض أكبر بكثير من فافيكون التبويب.</p>\n<h2 id=\"the-site-webmanifest-file\">ملف site.webmanifest</h2>\n<p>ملف site.webmanifest ملف JSON صغير يصف موقعك كتطبيق ويب قابل للتثبيت. يسرد اسم الموقع ولون السمة وملفات الأيقونة بأحجامها وأغراضها.</p>\n<p>المولد يكتب هذا الملف لك، بما فيه أيقونتا 192 و512 بكسل ووسوم الحجم الصحيحة. لا تحتاج إلى كتابة JSON يدويًا ولا تذكر صيغة البيان. ارفع الملف إلى جذر موقعك واربطه من مقتطف HTML. ولون السمة في البيان يلوّن شريط المتصفح في أندرويد عندما يكون موقعك مفتوحًا.</p>\n<h2 id=\"common-favicon-mistakes\">الأخطاء الشائعة مع الفافيكون</h2>\n<p>الخطأ الأكثر شيوعًا هو رفع شعار مفصل بنص صغير. عند 16 بكسل، يتحول الشعار إلى ضجيج رمادي والشعار ذو الخطوط الرفيعة إلى بقعة. بسّط العلامة أولًا ثم ولّد الحزمة.</p>\n<p>من الأخطاء الأخرى استخدام صورة مصدر منخفضة الدقة. صورة 32 بكسل ممددة إلى 512 لأيقونة أندرويد تبدو ناعمة وغير احترافية. وابدأ دائمًا بأكبر ملف شعار لديك. والخطأ الثالث هو نسيان خلفية أيقونة Apple Touch، فشعار شفاف على شاشة آيفون الرئيسية يحصل على زوايا سوداء تبدو كخطأ عرض.</p>\n<h2 id=\"updating-a-favicon-without-cache-trouble\">كيف تحدّث فافيكون دون مشاكل التخزين المؤقت</h2>\n<p>المتصفحات تخزن الفافيكون بشكل عدواني جدًا، أحيانًا لأسابيع. وبعد رفع حزمة جديدة، قد يستمر متصفحك في عرض الأيقونة القديمة رغم أن الملفات على الخادم جديدة.</p>\n<p>الحل الأبسط هو تحديث قسري للصفحة أو مسح ذاكرة المتصفح المؤقتة لذلك الموقع. في كروم، تحديث قسري بـCtrl وShift وR يجبر الأيقونة الجديدة غالبًا. وللزوار، تظهر الأيقونة الجديدة عندما تنتهي صلاحية ذاكرتهم المؤقتة أو عندما يزورون من جهاز جديد.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق لحزمة الفافيكون</h2>\n<p>ابدأ بشعار مربع بصيغة PNG أو SVG لا يقل عن 512 بكسل. اضبط الحشو لتتنفس العلامة، واختر لون خلفية ينجو في التبويبات الفاتحة والداكنة، وراجع المعاينتين قبل التنزيل.</p>\n<p>ارفع محتويات ZIP إلى جذر موقعك، والصق مقتطف HTML في قالب head المشترك، وأدرج البيان لأندرويد. ثم اختبر أيقونة التبويب وأيقونة الإشارات وأيقونة الشاشة الرئيسية على هاتف حقيقي.</p>\n<p>للخطوات الكاملة، اقرأ <a href=\"/ar/blog/kayfiyya-ins-ha-favicon/\">كيف تنشئ فافيكون</a>، ولرؤية كل حجم مشروحًا اقرأ <a href=\"/ar/blog/ahjam-favicon-mashruha/\">أحجام الفافيكون مشروحة: من 16×16 إلى 512×512</a>. ولإنشاء حزمتك الآن، افتح <a href=\"/ar/munshi-favicon/\">مولد الفافيكون</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما هو الفافيكون؟","answer":"الفافيكون أيقونة صغيرة تمثل موقع ويب في تبويبات المتصفح والإشارات المرجعية والسجل واختصارات الشاشة الرئيسية. الملف الكلاسيكي هو favicon.ico، لكن الإعداد الكامل يضم أيضًا أيقونات PNG وأيقونة Apple وملف بيان."},{"question":"هل أحتاج إلى فافيكون إذا كان موقعي صغيرًا؟","answer":"نعم، حتى موقع من صفحة واحدة يعرض أيقونة عامة أو فارغة في التبويب إذا لم يكن لديه واحد، وهذا يبدو مهملًا. إضافة فافيكون لا تكلف شيئًا وتساعد الزوار على إيجاد تبويبك مجددًا وتمنح موقعك مظهرًا مكتملًا."},{"question":"هل يمكنني استخدام صورة كفافيكون؟","answer":"يمكنك، لكن الصور نادرًا ما تعمل جيدًا. صورة مصغرة إلى 16 في 16 بكسل تتحول إلى بقعة لا يمكن التعرف عليها. شعار بسيط أو رمز أو حرف واحد بتباين جيد يُقرأ أفضل بكثير بحجم الفافيكون."},{"question":"ما الفرق بين favicon.ico وفافيكون PNG؟","answer":"صيغة ICO حاوية تستطيع حفظ أحجام أيقونات عدة في ملف واحد، وتدعمها المتصفحات منذ عقود. فافيكون PNG يحفظ حجمًا واحدًا، فيحتاج ملفات منفصلة لكل حجم. والحزمة الكاملة تضم كليهما."},{"question":"كم يستغرق إنشاء حزمة فافيكون؟","answer":"دقائق معدودة: ارفع شعارك واضبط الحشو ونصف قطر الزاوية ولون الخلفية وراجع المعاينتين الفاتحة والداكنة ونزّل ZIP. وتثبيت الملفات على موقعك يستغرق دقائق إضافية من الرفع واللصق."},{"question":"هل سيساعد الفافيكون موقعي على الترتيب في نتائج البحث؟","answer":"ليس مباشرة، فالفافيكون ليس عامل ترتيب، لكن بعض نتائج البحث تعرضه بجانب رابطك، ما قد يجعل نتيجتك أسهل رؤية ونقرًا. قيمته الحقيقية في العلامة التجارية والتعرف عليه في التبويبات والإشارات."}];
